-- CFA Study Hub: database setup.
-- Paste this whole file into Supabase → SQL Editor → New query, then click Run.
-- Safe to run more than once.

-- 1. One table holds everything. Each row belongs to one signed-in user.
create table if not exists public.docs (
  user_id    uuid        not null default auth.uid() references auth.users(id) on delete cascade,
  coll       text        not null,
  id         text        not null,
  data       jsonb       not null,
  updated_at timestamptz not null default now(),
  primary key (user_id, coll, id)
);

-- 2. Row-level security: you can only ever see and change your own rows.
alter table public.docs enable row level security;

drop policy if exists "own rows: read"   on public.docs;
drop policy if exists "own rows: insert" on public.docs;
drop policy if exists "own rows: update" on public.docs;
drop policy if exists "own rows: delete" on public.docs;
create policy "own rows: read"   on public.docs for select to authenticated using (auth.uid() = user_id);
create policy "own rows: insert" on public.docs for insert to authenticated with check (auth.uid() = user_id);
create policy "own rows: update" on public.docs for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own rows: delete" on public.docs for delete to authenticated using (auth.uid() = user_id);

revoke all on public.docs from anon;
grant select, insert, update, delete on public.docs to authenticated;

-- 3. Move your current hub data over (modules, Quant progress, plan order, starter cards).
--    It attaches to the user you created in Authentication → Users.
insert into public.docs (user_id, coll, id, data)
select u.id, v.coll, v.id, v.data
from (select id from auth.users order by created_at limit 1) u,
(values
  ('cards', 'starter-eth-1', $j${"back": "I Professionalism · II Integrity of Capital Markets · III Duties to Clients · IV Duties to Employers · V Investment Analysis, Recommendations & Actions · VI Conflicts of Interest · VII Responsibilities as a CFA Member or Candidate", "created": "2026-11-01", "due": "2026-11-02", "ease": 2.5, "front": "Name the seven Standards of Professional Conduct", "interval": 0, "reps": 0, "starter": true, "topic": "ethics"}$j$::jsonb),
